import{_ as t,o as a,c as r,a5 as i}from"./chunks/framework.BfQ7H7Qx.js";const g=JSON.parse('{"title":"01-identity-gateway — Identity, API Gateway & Edge Security (2 Modules)","description":"","frontmatter":{},"headers":[],"relativePath":"feature/modules/01-identity-gateway/README.md","filePath":"feature/modules/01-identity-gateway/README.md"}'),o={name:"feature/modules/01-identity-gateway/README.md"};function d(n,e,s,l,c,u){return a(),r("div",null,[...e[0]||(e[0]=[i('<h1 id="_01-identity-gateway-—-identity-api-gateway-edge-security-2-modules" tabindex="-1">01-identity-gateway — Identity, API Gateway &amp; Edge Security (2 Modules) <a class="header-anchor" href="#_01-identity-gateway-—-identity-api-gateway-edge-security-2-modules" aria-label="Permalink to &quot;01-identity-gateway — Identity, API Gateway &amp; Edge Security (2 Modules)&quot;">​</a></h1><p>&gt; <strong>Navigation:</strong> <a href="./../../README.html">← Feature Master Index</a> · <a href="./../README.html">← Modules Master Index</a> · <a href="./../../srs/01-authentication/README.html">SRS 3.2 Auth</a> · <a href="./../../srs/02-profile/README.html">SRS 3.3 Profile</a> · <a href="./../../../ba/README.html">BA Baseline</a> · <a href="./../../../rule/feature-workflow.html">Workflow Rule</a></p><p>Cross-cutting edge security, stateless RS256 JWT verification, inbound identity header sanitization, Redis token-bucket rate limiting, and universal user avatar/banner S3 delivery shared across all client surfaces.</p><hr><h2 id="_1-production-codebase-persistence-mapping" tabindex="-1">1. Production Codebase &amp; Persistence Mapping <a class="header-anchor" href="#_1-production-codebase-persistence-mapping" aria-label="Permalink to &quot;1. Production Codebase &amp; Persistence Mapping&quot;">​</a></h2><ul><li><strong>Primary Services:</strong> <code>brandhub-api-gateway</code> (<code>JwtAuthFilterGatewayFilterFactory</code>, <code>RateLimitGatewayFilterFactory</code>, <code>InternalHeaderSanitizerFilter</code>), <code>brandhub-business-service</code> (<code>AuthController</code>, <code>UserController</code>, <code>S3FileStorageServiceImpl</code>, <code>ImageValidator</code>), <code>brandhub-web</code>, and <code>brandhub-mobile-app</code>.</li><li><strong>Storage &amp; Runtime State:</strong><ul><li><strong>PostgreSQL 17:</strong> <code>users</code> (<code>avatar_url</code>, <code>banner_preset</code>, <code>banner_url</code>), <code>user_system_roles</code>, <code>user_refresh_tokens</code>.</li><li><strong>Redis 7.2:</strong> <code>jwt:blacklist:{jti}</code> (revoked access-token JTIs), <code>ratelimit:{route}:{subject}</code> (Lua sliding/token-bucket counters).</li><li><strong>AWS S3 (<code>brandhub-media-134875421878</code>):</strong> Publicly cached CDN/S3 object keys under <code>avatars/{userId}/*</code> and curated banner presets.</li></ul></li><li><strong>Related Canonical SRS Domains:</strong> <a href="./../../srs/01-authentication/README.html">01-authentication (<code>3.2.1</code>–<code>3.2.9</code>)</a> · <a href="./../../srs/02-profile/README.html">02-profile (<code>3.3.1</code>–<code>3.3.4</code>)</a> · <a href="./../../../api/rs256-jwt-flow.html">RS256 JWT Flow</a> · <a href="./../../../adr/adr-004-spring-cloud-gateway.html">ADR-004 Spring Cloud Gateway</a>.</li></ul><hr><h2 id="_2-consolidated-modules-2" tabindex="-1">2. Consolidated Modules (<code>2</code>) <a class="header-anchor" href="#_2-consolidated-modules-2" aria-label="Permalink to &quot;2. Consolidated Modules (`2`)&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">Module Slug</th><th style="text-align:left;">Scope &amp; Engineering Title</th><th style="text-align:left;">Core Codebase Touchpoints</th><th style="text-align:left;">Lifecycle Artefacts (<code>spec → plan → task → test</code>)</th></tr></thead><tbody><tr><td style="text-align:left;"><code>gateway-jwt-and-rate-limiting</code></td><td style="text-align:left;"><strong>API Gateway JWT Verification, Header Sanitization &amp; Rate Limiting</strong></td><td style="text-align:left;"><code>JwtAuthFilterGatewayFilterFactory</code>, <code>RateLimitGatewayFilterFactory</code>, <code>X-User-Id</code> / <code>X-User-Roles</code> header stripping &amp; injection, <code>/ws/chat</code> WebSocket upgrade auth</td><td style="text-align:left;"><a href="./gateway-jwt-and-rate-limiting/spec.html">Spec</a> · <a href="./gateway-jwt-and-rate-limiting/plan.html">Plan</a> · <a href="./gateway-jwt-and-rate-limiting/task.html">Task</a> · <a href="./gateway-jwt-and-rate-limiting/test.html">Test</a></td></tr><tr><td style="text-align:left;"><code>user-avatar-and-banner-presets</code></td><td style="text-align:left;"><strong>Unified People Avatars, Banner Presets &amp; S3 Image Upload Pipeline</strong></td><td style="text-align:left;"><code>UserController</code>, <code>ImageValidator</code> magic-byte check, deterministic initials/gradient fallback, <code>ProfileBannerPicker</code> &amp; S3 presigned/multipart upload</td><td style="text-align:left;"><a href="./user-avatar-and-banner-presets/spec.html">Spec</a> · <a href="./user-avatar-and-banner-presets/plan.html">Plan</a> · <a href="./user-avatar-and-banner-presets/task.html">Task</a> · <a href="./user-avatar-and-banner-presets/test.html">Test</a></td></tr></tbody></table><hr><h2 id="_3-verification-security-invariants" tabindex="-1">3. Verification &amp; Security Invariants <a class="header-anchor" href="#_3-verification-security-invariants" aria-label="Permalink to &quot;3. Verification &amp; Security Invariants&quot;">​</a></h2><ol><li>External callers can never spoof <code>X-User-Id</code>, <code>X-User-Email</code>, or <code>X-User-Roles</code>; <code>brandhub-api-gateway</code> strips inbound <code>X-User-*</code> headers before RS256 verification (<code>public.pem</code>).</li><li><code>brandhub-business-service</code> exclusively holds <code>private.pem</code> for signing JWTs (<code>ADR-004</code>), while downstream services trust verified gateway headers inside the private Docker/VPC network.</li><li>Avatar and banner uploads enforce strict MIME + magic-byte validation (<code>JPEG</code>, <code>PNG</code>, <code>WEBP</code>) and size caps prior to S3 persistence.</li></ol>',12)])])}const p=t(o,[["render",d]]);export{g as __pageData,p as default};
